"""Explain macro redefinition, conditional decrement and exchange results."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1541': ('안내문을 세 종류 찍다가 양식을 바꾸어 두 종류만 찍는다고 해 봅시다. 양식을 바꿔도 앞서 만든 안내문까지 사라지는 것은 아닙니다.', '소스 순서에 따라 달라지는 매크로와 생성 함수 목록을 읽습니다.', 'add·sub 아래에는 void, return, fetch를 쓰세요. and·or·xor 아래에는 void, fetch만 적고 양식 변경 지점을 표시하세요.', ['ATOMIC64_OPS는 여러 함수 생성 양식을 묶는 매크로입니다. 전처리는 실행 전에 코드의 매크로를 펼치는 단계입니다. 이 파일에서는 같은 이름의 양식을 중간에 바꾸므로 위에서 아래로 읽어야 합니다.', '첫 정의에는 ATOMIC64_OP, ATOMIC64_OP_RETURN, ATOMIC64_FETCH_OP 세 가지가 있습니다. 각각 값만 바꾸기, 바꾼 뒤 값 반환, 바꾸기 전 값 반환입니다. 이 정의로 add와 sub를 펼칩니다.', '그 뒤 #undef ATOMIC64_OPS는 그 시점부터 기존 정의를 없앱니다. 이어지는 #define은 같은 이름에 새 양식을 붙입니다. 새 정의에는 OP와 FETCH_OP만 있고 OP_RETURN은 없습니다.', '이 새 양식으로 and, or, xor를 펼칩니다. 따라서 이 파일은 generic_atomic64_and와 generic_atomic64_fetch_and를 만들지만 generic_atomic64_and_return은 만들지 않습니다. 비트 계산이 불가능해서가 아니라 선택한 함수 목록이 다르기 때문입니다.', '앞서 펼친 add와 sub의 코드가 나중 재정의로 소급해 삭제되지는 않습니다. 안내문 양식을 바꿔도 이미 인쇄한 종이는 남는 것과 비슷합니다. 같은 매크로 이름만 검색하지 말고 그 위치에서 어떤 정의가 적용되는지 확인하세요.', '헤더도 산술에는 세 종류, 비트 연산에는 두 종류를 선언하는 구성을 사용합니다. 함수 이름을 추측해 부르기보다 선언과 실제 생성 목록을 대조하세요. void는 결과 숫자 없음, return과 fetch는 각각 이후 값과 이전 값이라는 약속입니다.'], [('이 파일의 비트 연산 양식이 generic_atomic64_and_return도 만드나요?', ['네. 모든 연산은 언제나 세 종류를 만들어요', '아니요. 재정의 뒤에는 void와 fetch만 만들어요'], 'and를 펼치기 전에 OP_RETURN을 뺀 새 정의를 적용합니다. add_return이 있다고 and_return도 있을 것이라고 추측하면 안 됩니다.'), ('뒤에서 ATOMIC64_OPS를 바꾸면 앞서 만든 add 함수도 삭제되나요?', ['아니요. 새 정의는 이후 사용에 적용돼요', '네. 이미 펼친 코드까지 돌아가 지워요'], '전처리는 소스 순서로 진행됩니다. 앞서 만든 add·sub 함수는 남고, 이후 비트 함수의 생성 방식이 바뀝니다.')]), 'os1542': ('사탕이 있으면 한 개를 꺼내고, 없으면 그대로 두는 규칙을 생각해 봅시다. “한 개를 빼 보니 -1”이라는 계산 결과를 알려 줘도 실제 상자에 -1개를 저장하는 것은 아닙니다.', '조건 감소의 계산 결과와 실제 저장 결과를 구별합니다.', '초기 1이면 계산 0·저장 0·반환 0, 초기 0이면 계산 -1·저장 0·반환 -1의 표를 쓰세요.', ['generic_atomic64_dec_if_positive는 잠금 안에서 먼저 counter - 1을 val에 계산합니다. dec는 하나 줄이기입니다. val은 계산을 해 본 결과를 담는 지역 칸이고 원본 counter와는 별도입니다.', '다음 if (val >= 0)은 계산 결과가 0 이상인지 묻습니다. 맞을 때만 counter = val로 저장합니다. 조건에 맞지 않으면 원본을 그대로 둡니다. 검사와 저장이 같은 잠금 구간이어서 다른 참여 연산이 그 사이에 끼어들지 못합니다.', '초기값이 1이면 val=0입니다. 0도 0 이상이므로 저장하고 0을 반환합니다. 이 경우는 하나를 줄이는 데 성공했습니다. 모든 함수의 결과 0을 실패라고 읽으면 틀리는 이유입니다.', '초기값이 0이면 val=-1입니다. 음수라 저장하지 않으므로 원본은 0으로 남지만 반환은 -1입니다. 함수의 마지막은 return val이지 return counter가 아닙니다. 계산한 값과 보관된 값이 달라질 수 있습니다.', '정상적인 작은 음수 없는 자원 수에서는 반환값이 0 이상인지 보고 감소 여부를 판단할 수 있습니다. 이 예시는 그런 범위에서 읽는 연습입니다. 정수 표현 범위 끝의 계산까지 사탕 수처럼 무제한 정수로 해석하지 마세요.', '이 함수는 조건부 산술 연산입니다. 참조 수를 보호하는 전용 refcount API의 수명 관리 규칙을 모두 제공하는 것은 아닙니다. 감소가 안전하게 이루어졌다는 사실만으로 자료를 아무 때나 없애도 된다는 뜻은 아닙니다.'], [('초기 counter=0에서 dec_if_positive를 하면 반환과 저장은?', ['반환 -1, 저장 -1이에요', '반환 -1, 저장 0이에요'], 'val은 -1이지만 val >= 0이 거짓이라 저장하지 않습니다. 계산 결과는 반환하므로 -1을 받고, 원본은 0으로 남아요.'), ('초기값 1에서 결과 0을 받았어요. 감소에 실패한 건가요?', ['아니요. 1에서 0으로 줄인 성공이에요', '네. 모든 함수에서 0은 실패예요'], '계산한 0은 저장 조건인 0 이상을 만족합니다. 실제 counter도 0으로 바뀌므로 감소 성공이에요. 반환값의 뜻은 함수별로 읽어야 합니다.')]), 'os1543': ('숫자판이 아직 5라면 9로 바꾸라는 부탁을 생각해 봅시다. 누군가 이미 6으로 바꿨다면 무조건 덮지 않고, 지금 확인한 6을 알려 주는 방식입니다.', '비교와 조건 교환을 한 번에 수행하고 이전 값으로 성공을 판단합니다.', '현재 5·기대 4·새 값 9이면 반환 5·저장 5, 기대 5이면 반환 5·저장 9라고 적으세요.', ['cmpxchg는 compare exchange, 비교한 뒤 맞으면 교환하기를 줄인 이름입니다. v는 대상 자료, o는 기대하는 이전 값, n은 바꿀 새 값입니다. 세 인자의 역할을 따로 적으면 읽기 쉽습니다.', '잠금을 잡고 원본 counter를 val에 먼저 복사합니다. 그다음 val == o이면 counter에 n을 저장합니다. ==는 같은지 비교하는 기호입니다. 다르면 원본에 새 값을 쓰지 않습니다.', '마지막에는 조건이 맞았는지와 관계없이 val을 반환합니다. 따라서 반환형은 이전 숫자를 담는 s64이며 참·거짓만 돌려주는 함수가 아닙니다. 성공 여부는 받은 값이 기대값 o와 같은지 비교합니다.', '현재 5, 기대 4, 새 값 9라면 비교가 실패하여 저장은 5, 반환도 5입니다. 현재 5, 기대 5라면 저장은 9지만 반환은 여전히 5입니다. 기대값과 비교하지 않고 반환값이 1인지 검사하면 성공을 잘못 판단합니다.', '기대값이 0인 경우 성공하면서 0을 반환할 수도 있습니다. 비교와 교환을 같은 잠금 안에서 처리하므로 별도 read 뒤 if와 set을 하는 코드처럼 그 사이 다른 갱신이 끼어드는 것은 막습니다.', '다만 값의 과거 변화까지 기억하는 기능은 없습니다. 예를 들어 5가 6으로 바뀌었다 다시 5가 되면 비교는 5와 같다고 볼 수 있습니다. 이런 문제를 ABA라고 부릅니다. 주소가 가리키는 자료의 수명이나 이런 과거 변화가 중요한 설계는 별도 규칙이 필요합니다.'], [('현재 5에서 기대값 4, 새 값 9로 cmpxchg를 하면?', ['반환 0, 저장 9예요', '반환 5, 저장 5예요'], '5와 4가 달라서 저장하지 않습니다. 실패여도 확인한 이전 값 5를 반환해요. 실패하면 항상 0을 준다는 불리언 규칙이 아닙니다.'), ('교환에 성공했는지는 어떻게 알 수 있나요?', ['반환값과 기대값이 같은지 비교해요', '반환값이 반드시 1인지 확인해요'], '이 함수는 비교할 때 본 이전 값을 돌려줍니다. 그것이 기대값과 같았다면 교환이 이루어진 것이에요. 기대값 0에서도 성공할 수 있으므로 1 검사나 단순 if로 바꾸면 안 됩니다.')]), 'os1544': ('새 쪽지를 꽂으며 원래 꽂혀 있던 쪽지를 받아 오는 일을 한 번에 한다고 생각해 봅시다. 기존 내용이 무엇인지 조건을 걸지 않고 바꾸는 방식입니다.', '무조건 교체하는 xchg와 조건이 필요한 cmpxchg를 구별합니다.', 'counter=8 → val에 8 복사 → counter에 3 저장 → 8 반환을 그리세요. 기대값 비교 칸이 없다는 점을 표시하세요.', ['generic_atomic64_xchg는 대상 v와 새 값 new를 받습니다. xchg는 exchange, 교환의 줄임말입니다. 이 함수에는 cmpxchg의 기대값 o 인자가 없습니다.', '객체 주소에 맞는 잠금을 골라 잡은 뒤 val = v->counter로 이전 값을 복사합니다. 초기값 8이라면 val은 8입니다. 그다음 v->counter = new로 새 값을 저장합니다.', 'new가 3이면 원본은 3으로 바뀝니다. 비교하는 if문이 없으므로 이전 값이 8이든 다른 값이든 새 값으로 교체합니다. 잠금을 풀고 돌려주는 것은 val의 이전 값 8입니다.', '복사와 저장은 한 번의 잠금 안에서 이루어집니다. 따라서 그 사이 다른 참여 연산이 같은 counter를 바꾸지 못합니다. 이전 값 가져오기와 새 값 넣기를 하나로 묶은 연산입니다.', '따로 read한 뒤 set을 부르면 두 호출 사이에 다른 작업이 값을 바꿀 수 있습니다. A가 8을 읽고 B가 9를 저장한 뒤 A가 3을 쓰면, A가 읽은 8은 실제로 교체 직전에 있던 9와 다릅니다. xchg는 자신의 교환 직전 값을 같은 보호 구간에서 확보합니다.', '항상 바꾸려면 xchg, 특정 기대값일 때만 바꾸려면 cmpxchg의 계약을 확인하세요. 숫자 교환이 안전하다는 사실만으로 그 숫자와 관련된 모든 자료의 사용 기간까지 보호되지는 않습니다. 실제 자료 접근과 수명은 필요한 규칙을 따로 지켜야 합니다.'], [('현재 counter=8에 xchg(new=3)를 하면 반환값과 저장값은?', ['반환 3, 저장 8이에요', '반환 8, 저장 3이에요'], '이전 8을 지역 칸에 보관하고 새 3을 원본에 씁니다. 마지막에는 보관한 8을 반환해요. 받은 결과를 새 값으로 착각하지 마세요.'), ('xchg가 새 값을 쓰려면 기대값과 먼저 같아야 하나요?', ['아니요. 비교 없이 새 값으로 바꿔요', '네. 항상 expected 인자가 필요해요'], '이 함수의 인자는 대상과 새 값이며 조건 비교가 없습니다. 기대값이 맞을 때만 바꾸는 것은 cmpxchg의 동작이에요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_381.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
